function useStored(key, init){
 const [value,setValue]=useState(()=>{try{return JSON.parse(localStorage.getItem(key))??init}catch{return init}});
 useEffect(()=>localStorage.setItem(key,JSON.stringify(value)),[key,value]);
 return [value,setValue];
}

const AUDIO_LOCALES={English:'en-GB',Spanish:'es-ES',French:'fr-FR','en-GB':'en-GB','es-ES':'es-ES','fr-FR':'fr-FR'};
function speakText(text, rate=0.9, language='English'){
 if(!('speechSynthesis' in window)) return false;
 const locale=AUDIO_LOCALES[language]||language;
 window.speechSynthesis.cancel();
 const utterance=new SpeechSynthesisUtterance(text);
 utterance.lang=locale; utterance.rate=rate; utterance.pitch=1;
 const voices=window.speechSynthesis.getVoices();
 const targetLanguage=locale.toLowerCase().split('-')[0];
 const targetVoice=voices.find(v=>v.lang?.toLowerCase()===locale.toLowerCase())||voices.find(v=>v.lang?.toLowerCase().split('-')[0]===targetLanguage);
 // Never assign a voice from another language (for example, the browser's Turkish default).
 if(targetVoice) utterance.voice=targetVoice;
 window.speechSynthesis.speak(utterance);
 return utterance;
}
let activeSpeechId=null,activeRecordedAudio=null;
function SpeakButton({text,label='Listen',className='',language='English'}){const [active,setActive]=useState(false),idRef=React.useRef(Symbol('speech'));useEffect(()=>{const stop=e=>{if(e.detail!==idRef.current)setActive(false)};window.addEventListener('contexta-speech-change',stop);return()=>window.removeEventListener('contexta-speech-change',stop)},[]);const play=e=>{e?.stopPropagation();if(active){window.speechSynthesis?.cancel();activeSpeechId=null;setActive(false);return}window.dispatchEvent(new window.CustomEvent('contexta-speech-change',{detail:idRef.current}));activeSpeechId=idRef.current;const u=speakText(text,0.9,language);if(u){setActive(true);u.onend=()=>{activeSpeechId=null;setActive(false)};u.onerror=()=>{activeSpeechId=null;setActive(false)}}};return <button type="button" onClick={play} className={`inline-flex items-center justify-center gap-1.5 rounded-full bg-blue-50 text-brand transition hover:bg-blue-100 ${className}`} aria-label={active?`Stop: ${text}`:`${label}: ${text}`}>{active?<Pause size={16}/>:<Volume2 size={16}/>}</button>}

function RecordedAudioButton({src,label='Listen · Spanish male voice',playingLabel='Stop audio',className='',onProgress,onPlayingChange}){
 const [playing,setPlaying]=useState(false);const audioRef=React.useRef(null),idRef=React.useRef(Symbol('recorded-audio'));
 const updatePlaying=value=>{setPlaying(value);onPlayingChange?.(value)};
 useEffect(()=>{const stop=e=>{if(e.detail!==idRef.current)updatePlaying(false)};window.addEventListener('contexta-recorded-audio-change',stop);return()=>window.removeEventListener('contexta-recorded-audio-change',stop)},[]);
 const toggle=event=>{event?.preventDefault();event?.stopPropagation();if(playing){audioRef.current?.pause();if(activeRecordedAudio===audioRef.current)activeRecordedAudio=null;updatePlaying(false);return}activeRecordedAudio?.pause();window.dispatchEvent(new window.CustomEvent('contexta-recorded-audio-change',{detail:idRef.current}));if(!audioRef.current||audioRef.current.src!==new URL(src,window.location.href).href)audioRef.current=new Audio(src);const audio=audioRef.current;activeRecordedAudio=audio;audio.onended=()=>{if(activeRecordedAudio===audio)activeRecordedAudio=null;onProgress?.(1);updatePlaying(false)};audio.onerror=()=>{if(activeRecordedAudio===audio)activeRecordedAudio=null;updatePlaying(false)};audio.ontimeupdate=()=>{if(audio.duration)onProgress?.(audio.currentTime/audio.duration)};audio.currentTime=0;const request=audio.play();request?.catch?.(()=>{if(activeRecordedAudio===audio)activeRecordedAudio=null;updatePlaying(false)});updatePlaying(true)};
 useEffect(()=>()=>{audioRef.current?.pause();if(activeRecordedAudio===audioRef.current)activeRecordedAudio=null},[src]);
 return <button type="button" onClick={toggle} aria-label={playing?'Stop audio':label} className={`inline-flex items-center gap-2 rounded-xl bg-brand px-4 py-2.5 text-sm font-extrabold text-white shadow-sm transition hover:bg-[#0D4A83] ${className}`}><span className="grid h-7 w-7 place-items-center rounded-full bg-white/15">{playing?<Pause size={14}/>:<Play size={14} fill="currentColor"/>}</span>{playing?playingLabel:label}</button>
}

