function getArticleGender(word,language,sentence=''){
 const w=word.toLowerCase();
 if(language==='Spanish'){
  if(['el','los','un','unos','del','al'].includes(w))return 'masculine';
  if(['la','las','una','unas'].includes(w))return 'feminine';
 }
 if(language==='French'){
  if(['le','un','du','au'].includes(w))return 'masculine';
  if(['la','une'].includes(w))return 'feminine';
  if(w==='les'&&/villages/i.test(sentence))return 'masculine';
 }
 return null;
}

