const spanishQuestions=[{text:['Ana ',' el tren a Valencia.'],answer:'toma',choices:['toma','tomas','tomar']},{text:['La playa está casi ','.'],answer:'vacía',choices:['fría','pequeña','vacía']},{text:['Ana encuentra un banco junto al ','.'],answer:'puerto',choices:['puerto','tren','libro']}];
const frenchQuestions=[{text:['Camille ',' le train pour Nice.'],answer:'prend',choices:['prend','prendre','prends']},{text:['La plage est presque ','.'],answer:'vide',choices:['fraîche','petite','vide']},{text:['Camille trouve un banc près du ','.'],answer:'port',choices:['port','train','livre']}];
