 Spanish:{va:['ir','presente · 3.ª persona singular'],lleva:['llevar','presente · 3.ª persona singular'],habla:['hablar','presente · 3.ª persona singular'],elige:['elegir','presente · 3.ª persona singular'],volver:['volver','infinitivo'],planean:['planear','presente · 3.ª persona plural'],cambia:['cambiar','presente · 3.ª persona singular'],empieza:['empezar','presente · 3.ª persona singular'],llover:['llover','infinitivo'],encuentran:['encontrar','presente · 3.ª persona plural'],comparten:['compartir','presente · 3.ª persona plural'],esperan:['esperar','presente · 3.ª persona plural'],termina:['terminar','presente · 3.ª persona singular'],regresan:['regresar','presente · 3.ª persona plural']},
