function getGrammarInsight(word,info,language,sentence=''){
 const w=word.toLowerCase();
 const articleGender=getArticleGender(word,language,sentence);
 if(articleGender)return {kind:`${articleGender==='feminine'?'Feminine':'Masculine'} article`,base:word,form:'article',gender:articleGender,explanation:`This article agrees with a ${articleGender} noun in the sentence.`};
 const spanishVerb=language==='Spanish'?getSpanishVerbData(word):null;if(spanishVerb)return {kind:'Verb in context',base:spanishVerb.lemma,form:spanishVerb.form,explanation:spanishVerb.explanation,conjugation:spanishVerb.conjugation};
 const verbs={
  English:{took:['take','past simple · irregular','“Took” is the past form of “take”. It describes a completed action.'],wanted:['want','past simple · regular','The ending -ed marks a completed past action.'],moved:['move','past simple · regular','The final -e is followed by -d in the past.'],watched:['watch','past simple · regular','Add -ed to form the regular past tense.'],arrived:['arrive','past simple · regular','The verb describes a completed arrival in the past.'],felt:['feel','past simple · irregular','“Felt” is the irregular past form of “feel”.'],bought:['buy','past simple · irregular','“Bought” is the irregular past form of “buy”.'],found:['find','past simple · irregular','“Found” is the irregular past form of “find”.'],opened:['open','past simple · regular','Add -ed to describe this completed action.']},
  Spanish:{toma:['tomar','presente · 3.ª persona singular','“Toma” agrees with Ana: ella toma. Regular -ar verbs use -a with él/ella.'],quiere:['querer','presente · 3.ª persona singular','“Querer” changes e → ie in the present: ella quiere.'],pasar:['pasar','infinitivo','The infinitive follows “quiere”: quiere pasar. The second verb is not conjugated.'],mira:['mirar','presente · 3.ª persona singular','The subject is ella, so mirar becomes mira.'],llega:['llegar','presente · 3.ª persona singular','“Llega” describes what she does in the present-tense story.'],brilla:['brillar','presente · 3.ª persona singular','The subject is el sol, so the verb ends in -a.'],está:['estar','presente · 3.ª persona singular','“Está” is an irregular form of estar, used here for a temporary state.'],compra:['comprar','presente · 3.ª persona singular','A regular -ar verb: ella compra.'],encuentra:['encontrar','presente · 3.ª persona singular','This stem-changing verb changes o → ue: encuentra.'],abre:['abrir','presente · 3.ª persona singular','A regular -ir verb: ella abre.']},
  French:{prend:['prendre','présent · 3e personne du singulier','“Prend” agrees with Camille: elle prend. Prendre is irregular.'],veut:['vouloir','présent · 3e personne du singulier','“Veut” is the irregular present form used with il or elle.'],passer:['passer','infinitif','The infinitive follows “veut”: elle veut passer. The second verb stays unconjugated.'],regarde:['regarder','présent · 3e personne du singulier','A regular -er verb: elle regarde.'],arrive:['arriver','présent · 3e personne du singulier','The final -e marks the il/elle present form.'],brille:['briller','présent · 3e personne du singulier','The subject is le soleil: il brille.'],est:['être','présent · 3e personne du singulier','“Est” is the irregular il/elle form of être.'],achète:['acheter','présent · 3e personne du singulier','The stem changes e → è before a silent ending: elle achète.'],trouve:['trouver','présent · 3e personne du singulier','A regular -er verb: elle trouve.'],ouvre:['ouvrir','présent · 3e personne du singulier','Ouvrir is irregular but uses the form “elle ouvre”.']}
 };
 if(verbs[language]?.[w]){const [base,form,explanation]=verbs[language][w];return {kind:'Verb in context',base,form,explanation,conjugation:conjugationTables[language]?.[w]||null}}
 if(curriculumVerbData[language]?.[w]){const [base,form]=curriculumVerbData[language][w];return {kind:'Verb in context',base,form,explanation:`“${word}” is the ${form} form used in this sentence. Transform it to see how tense, polarity, and sentence type change the meaning.`,conjugation:null}}
 const role=(info.role||'').toLowerCase();
 if(/verb|verbo|verbe/.test(role))return {kind:'Verb in context',base:word,form:info.role,explanation:'Notice who performs the action, when it happens, and how the verb form agrees with its subject.'};
 if(/adjective|adjetivo|adjectif/.test(role))return {kind:'Describing word',base:word,form:info.role,explanation:language==='English'?'This adjective adds information about a noun.':'The adjective describes a noun and may change to agree with its gender or number.'};
 if(/noun|sustantivo|nom/.test(role))return {kind:'Noun in context',base:word,form:info.role,explanation:'Look at the article and surrounding words to understand number and grammatical gender.'};
 const functionWords={English:['the','a','an','to','by','as','through','near','and','of'],Spanish:['el','la','los','un','una','a','por','del','al','y','su'],French:['le','la','les','un','une','du','au','par','pour','et','son']};
 if(functionWords[language]?.includes(w))return {kind:'Grammar word',base:word,form:'article / connector',explanation:'This small word connects ideas or helps the noun fit correctly into the sentence.'};
 return {kind:'Word in context',base:word,form:info.role,explanation:'Use the words before and after it to notice its role and meaning in this sentence.'};
}

const exampleTranslations={
 English:{saturday:'We commonly arrange meetings for Saturday.',morning:'The streets are peaceful during the morning.',took:'She traveled to work by bus.',early:'I woke up before the usual time today.',train:'The train departs at nine.',escape:'They got away from the busy city.',noise:'The noise prevents me from sleeping.',quiet:'We found a peaceful café.',sea:'Their hotel has a view of the sea.',countryside:'He was raised in a rural area.',villages:'The road links three small villages.',beyond:'The mountains are on the far side of the lake.',arrived:'We reached the place just before lunch.',fresh:'Open the window to let clean air in.',beach:'The children played beside the sea.',empty:'There was nothing and nobody in the room.',bought:'I purchased a ticket online.',warm:'Would you like a heated drink?',bench:'They sat together on a seat in the park.',pier:'We walked to the far end of the pier.',journey:'The trip lasted two hours.'},
 Spanish:{},French:{}
};
